export const ReferenceDocumentCategoryKeyToLabel = {
  'InspectionForms': 'Inspection Forms',
  'FacilitySafety': 'Facility Safety',
  'HAZCOM': 'HAZCOM',
  'SDS': 'SDS',
  'SPCC': 'SPCC',
  'EmergencyEvacuation': 'Emergency-Evacuation',
  'TrainingSPOCResources': 'Training-SPOC Resources'
} as const;
export type ReferenceDocumentCategoryKey = keyof typeof ReferenceDocumentCategoryKeyToLabel;

export interface ReferenceDocument {
  /**
   * @displayName Reference Document ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Reference Document Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  referenceDocumentName: string;
  /**
   * @displayName Active
   * @validationRule Required for create/update operations
   */
  active: boolean;
  /**
   * @displayName Category
   * @validationRule Required for create/update operations
   */
  categoryKey: ReferenceDocumentCategoryKey;
  /**
   * @displayName SharePoint URL
   * @validationRule Required for create/update operations
   */
  sharePointURL: string;
  /**
   * @displayName Title
   * @validationRule Required for create/update operations
   */
  title: string;
}

export const _ReferenceDocument = 'ReferenceDocument' as const;